import {groupsAt,roundBrief,boundsForHole,atlasPosition,clock,situation} from './play-model.js';
import {bandon} from './bandon-data.js';
import {createCourseMap} from './course-map.js';
const $=s=>document.querySelector(s),L=window.L;
let minute=0,hole=1,selected=8,choice='auto',started=false,ended=false,running=false,follow=true,mode='atlas',timer,lastState='normal',lastHole=1,geo=null,atlas=null,toastTimer,events=[];
const groupMarkers=new Map(),holeImages=new Map(),holeButtons=new Map(),rows=new Map();
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
function addEvent(message){events.unshift({message,time:clock(510+minute)});events=events.slice(0,5);$('#updates').replaceChildren(...events.map(e=>{const el=document.createElement('div');el.className='update';const text=document.createElement('span'),time=document.createElement('small');text.textContent=e.message;time.textContent=e.time+' · simulated';el.append(text,time);return el;}));$('#update-count').textContent=events.length;}
function ensureHole(h){if(holeImages.has(h))return;const b=boundsForHole(h),n=String(h).padStart(2,'0');const image=L.imageOverlay(`assets/bandon/hole-${n}.svg`,b,{interactive:true,attribution:'Hole artwork: CoursePreview · independent concept demo'}).addTo(atlas);image.on('click',()=>selectHole(h));L.marker([b[1][0]+35,b[0][1]+55],{interactive:false,icon:L.divIcon({className:'',html:`<div class="hole-map-label">HOLE ${n} · PAR ${bandon.holePar[h]}</div>`,iconSize:[150,20]})}).addTo(atlas);holeImages.set(h,image);}
function selectHole(h,{camera=true}={}){hole=Math.max(1,Math.min(18,h));if(camera&&atlas&&mode==='atlas'){ensureHole(hole);atlas.fitBounds(boundsForHole(hole),{paddingTopLeft:[55,130],paddingBottomRight:[55,145],animate:!matchMedia('(prefers-reduced-motion: reduce)').matches,maxZoom:1});}for(const [h,b] of holeButtons)b.setAttribute('aria-pressed',String(h===hole));$('#hole-title').textContent=`Hole ${String(hole).padStart(2,'0')} · Par ${bandon.holePar[hole]}`;$('#traffic-title').textContent=`Hole ${String(hole).padStart(2,'0')} traffic`;$('#flyover-link').href=`course-preview.html?hole=${hole}`;$('#prev').disabled=hole===1;$('#next').disabled=hole===18;updateDetails();}
function setFollow(value){follow=value;$('#follow').classList.toggle('active',follow);$('#follow').textContent=follow?'◎ Following my group':'◎ Follow my group';}
function updateDetails(){const groups=groupsAt(minute,choice);for(const g of groups){const row=rows.get(g.id);row.element.hidden=g.hole!==hole;row.element.classList.toggle('active',selected===g.id);row.detail.textContent=g.stale?'Last demo observation · stale':`${Math.round(g.fraction*100)}% of demo hole`;row.stage.textContent=g.id===8?'You':'View →';}const sel=groups.find(g=>g.id===selected);$('#selection-detail').textContent=`Selected: Group ${String(selected).padStart(2,'0')} · hole ${sel.hole}. ${sel.stale?'Tracking interruption: its marker is frozen.':'Illustrative position on hole artwork, not measured GPS.'}`;}
function update(){const groups=groupsAt(minute,choice),own=groups.find(g=>g.id===8),brief=roundBrief(minute,choice);for(const g of groups){if(!atlas)continue;ensureHole(g.hole);const pos=atlasPosition(g);let marker=groupMarkers.get(g.id);if(!marker){marker=L.marker(pos,{icon:L.divIcon({className:'',html:`<div class="group-pin ${g.id===8?'you':''}">${String(g.id).padStart(2,'0')}</div>`,iconSize:[35,35],iconAnchor:[17,17]})}).on('click',()=>{selected=g.id;setFollow(false);selectHole(groupsAt(minute,choice).find(x=>x.id===g.id).hole,{camera:false});notify(`Group ${String(g.id).padStart(2,'0')} selected. Open round details for its status.`);}).addTo(atlas);groupMarkers.set(g.id,marker);}else marker.setLatLng(pos);const el=marker.getElement()?.firstElementChild;if(el){el.classList.toggle('selected',selected===g.id);el.classList.toggle('stale',g.stale);}}
 if(follow&&running&&mode==='atlas'){if(own.hole!==hole)selectHole(own.hole);else atlas?.panTo(atlasPosition(own),{animate:false});}
 $('#brief-title').textContent=started?brief.title:'A clearer picture of the course.';$('#brief-message').textContent=started?brief.message:'Start a round to watch your group and the traffic ahead change over time.';$('#own-hole').innerHTML=String(own.hole).padStart(2,'0')+' <small>/ 18</small>';$('#finish').textContent=brief.finish;$('#demo-time').textContent=clock(510+minute)+' · simulated';$('#timeline-label').textContent=Math.floor(minute)+' simulated minutes';if(document.activeElement!==$('#timeline'))$('#timeline').value=Math.floor(minute);$('#round-state').textContent=ended?'ROUND ENDED':running?'IN PROGRESS':started?'PAUSED':'NOT STARTED';$('#live-badge').innerHTML='<i></i> '+(running?'DEMO RUNNING':started?'DEMO PAUSED':'DEMO READY');$('#pause').disabled=!started||ended;$('#pause').textContent=running?'Ⅱ Pause':'▷ Resume';$('#end').disabled=!started||ended;$('#start-card').hidden=started||mode==='geo';updateDetails();
 if(started&&brief.state!==lastState){addEvent(brief.message);notify(brief.message);lastState=brief.state;}if(started&&own.hole!==lastHole){addEvent(`Your group entered hole ${own.hole}.`);lastHole=own.hole;}}
function pause(){running=false;clearInterval(timer);}
function run(){if(ended)return;running=true;clearInterval(timer);timer=setInterval(()=>{minute=Math.min(245,minute+Number($('#speed').value)*.25);update();if(minute>=245)endRound();},250);update();}
function startRound(){started=true;ended=false;selected=8;setFollow(true);selectHole(groupsAt(minute,choice).find(g=>g.id===8).hole);addEvent('Your round started. Group 08 is sharing a simulated position.');run();notify('You’re on the course. Tap a group, drag the map, or follow your round.');}
function endRound(){pause();ended=true;geo?.stopGPS();addEvent('Round ended. The $5 credit is a demo concept; no money was issued.');update();notify('Demo round finished. Reset in Demo controls to try again.');}
for(let h=1;h<=18;h++){const b=document.createElement('button');b.textContent=String(h).padStart(2,'0');b.setAttribute('aria-label','Explore hole '+h);b.onclick=()=>{setFollow(false);selectHole(h);};$('#hole-picker').append(b);holeButtons.set(h,b);}
for(let id=4;id<=11;id++){const element=document.createElement('button');element.className='group-row';const badge=document.createElement('b'),label=document.createElement('span'),name=document.createElement('span'),detail=document.createElement('small'),stage=document.createElement('span');badge.textContent=String(id).padStart(2,'0');name.textContent=id===8?'Your group':'Group '+String(id).padStart(2,'0');label.append(name,detail);element.append(badge,label,stage);element.onclick=()=>{selected=id;setFollow(false);selectHole(groupsAt(minute,choice).find(g=>g.id===id).hole);update();};rows.set(id,{element,detail,stage});$('#group-list').append(element);}
if(L){atlas=L.map('atlas',{crs:L.CRS.Simple,minZoom:-4,maxZoom:2,zoomSnap:.25,attributionControl:true}).setView([400,225],-.5);atlas.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');atlas.on('dragstart',()=>setFollow(false));ensureHole(1);$('#map-loading').hidden=true;}else $('#map-loading').textContent='The map library could not load. Please reload this page.';
$('#start').onclick=startRound;$('#pause').onclick=()=>{if(running){pause();update();}else run();};$('#end').onclick=endRound;$('#overview').onclick=()=>{if(mode==='geo'){geo?.overview();return;}setFollow(false);for(let h=1;h<=18;h++)ensureHole(h);atlas?.fitBounds([[-1900,0],[800,3400]],{paddingTopLeft:[35,90],paddingBottomRight:[35,130]});};$('#follow').onclick=()=>{if(mode==='geo')return;selected=8;setFollow(true);selectHole(groupsAt(minute,choice).find(g=>g.id===8).hole);update();};$('#prev').onclick=()=>{setFollow(false);selectHole(hole-1);};$('#next').onclick=()=>{setFollow(false);selectHole(hole+1);};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$('#atlas').hidden=mode!=='atlas';$('#geographic').hidden=mode!=='geo';$('#location').hidden=mode!=='geo';$('#follow').hidden=mode==='geo';$('#start-card').hidden=started||mode==='geo';document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('#map-caption').textContent=mode==='geo'?'REAL GEOGRAPHIC MAP · OPTIONAL DEVICE GPS · NO SHARED GROUP FEED':'ILLUSTRATED HOLE ATLAS · PANELS ARRANGED FOR BROWSING, NOT GEOGRAPHIC POSITION';$('#map-help').querySelector('strong').textContent=mode==='geo'?'Your real location.':'Explore the course.';$('#map-help').querySelector('span').textContent=mode==='geo'?'Enable GPS to see your device. Demo groups appear only on the hole atlas.':'Pan, zoom, or tap a group. Your simulation continues while you explore.';if(mode==='geo'&&!geo&&L){geo=createCourseMap($('#geographic'),{L,onStatus:text=>{if(mode==='geo')$('#map-help').querySelector('span').textContent=text;notify(text);}});geo.setCourse({id:'bandon',center:[43.187,-124.391]});}requestAnimationFrame(()=>{if(mode==='geo')geo?.resize();else atlas?.invalidateSize();});});
$('#location').onclick=()=>{if(!window.isSecureContext){notify('GPS requires HTTPS or localhost.');return;}geo?.startGPS();};$('#settings').onclick=()=>{const open=$('#controls').hidden;$('#controls').hidden=!open;$('#settings').setAttribute('aria-expanded',String(open));};$('#close-controls').onclick=()=>{$('#controls').hidden=true;$('#settings').setAttribute('aria-expanded','false');};$('#scenario').onchange=e=>{choice=e.target.value;update();};$('#timeline').oninput=e=>{minute=+e.target.value;update();};$('#reset').onclick=()=>{pause();geo?.stopGPS();minute=0;selected=8;started=false;ended=false;choice='auto';events=[];lastState='normal';lastHole=1;$('#scenario').value='auto';$('#updates').replaceChildren();$('#update-count').textContent='0';$('#start-card').hidden=mode==='geo';setFollow(true);selectHole(1);update();};$('#sheet-toggle').onclick=()=>{const open=document.body.classList.toggle('sheet-open');$('#sheet-toggle').setAttribute('aria-expanded',String(open));$('#sheet-toggle').textContent=open?'Close round details ↓':'Your round & traffic ↑';};window.addEventListener('pagehide',()=>{pause();geo?.stopGPS();});selectHole(1);update();
